const payload = $json.body ?? $json;
const data = payload.data ?? {};
const key = data.key ?? {};
const message = data.message ?? {};
const remoteJid = String(key.remoteJid ?? data.remoteJid ?? '');
const messageTypeRaw = String(data.messageType ?? '');
const isReaction = messageTypeRaw === 'reactionMessage' || Boolean(message.reactionMessage);
const text = String(message.conversation ?? message.extendedTextMessage?.text ?? message.imageMessage?.caption ?? '').trim();
const simplified = text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const isImage = messageTypeRaw === 'imageMessage' || Boolean(message.imageMessage);
let intent = 'other';
if (isImage) intent = 'receipt';
else if (/(^|\b)(parar|para|cancelar|cancela|sair|remover|remove|tirar|tira|nao quero|não quero)(\b|$)/.test(simplified)) intent = 'stop';
else if (/^(sim|quero|pode|pode enviar|manda|envia|vou querer)$/.test(simplified)) intent = 'affirmative';
else if (/^(nao|não|agora nao|agora não)$/.test(simplified)) intent = 'negative';
else if (/(kit|matematica|matemática|comprar|adquirir|atividades)/.test(simplified)) intent = 'purchase';
const externalId = String(key.id ?? data.id ?? '');
const timestamp = Number(data.messageTimestamp ?? Math.floor(Date.now() / 1000));
const ignored = payload.event !== 'messages.upsert' || !externalId || Boolean(key.fromMe) || remoteJid.endsWith('@g.us') || isReaction || (!text && !isImage);
return [{ json: {
  externalId, instance: String(payload.instance ?? ''),
  whatsappId: remoteJid, phone: remoteJid.split('@')[0].replace(/\D/g, ''),
  displayName: String(data.pushName ?? '').slice(0, 120), fromMe: Boolean(key.fromMe),
  isGroup: remoteJid.endsWith('@g.us'), messageType: isReaction ? 'reaction' : (isImage ? 'image' : 'text'),
  text: text.slice(0, 4000), intent, ignored,
  mediaReference: String(message.imageMessage?.url ?? (isImage ? 'evolution-media:' + externalId : '')),
  eventAt: new Date(timestamp * 1000).toISOString()
} }];

const state = String($json.state ?? 'new');
const intent = String($json.intent ?? 'other');
let route = 'duplicate';
if (!$json.inserted) route = 'duplicate';
else if (intent === 'stop') route = 'stop';
else if (intent === 'purchase') route = 'offer';
else if (state === 'stopped') route = 'duplicate';
else if (state === 'awaiting_consent') route = 'materials';
else if (intent === 'receipt' && state === 'awaiting_payment') route = 'receipt';
return [{ json: { ...$json, route } }];

const fs = require('fs');
const path = require('path');
const manifestPath = '/files/manifest.json';
if (!fs.existsSync(manifestPath)) throw new Error('Copie manifest.example.json para manifest.json e configure os materiais.');
const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
if (!Array.isArray(manifest.documents) || manifest.documents.length !== 9) throw new Error('O manifesto precisa conter nove PDFs.');
const base = $('Route State').item.json;
return manifest.documents.sort((a,b) => a.order - b.order).map((doc) => {
  const filePath = path.join('/files', doc.file);
  if (!fs.existsSync(filePath)) throw new Error('PDF ausente em /files: ' + doc.file);
  const documentBase64 = fs.readFileSync(filePath).toString('base64');
  return { json: { ...base, file: filePath, displayName: doc.displayName, documentBase64, driveUrl: manifest.driveUrl || base.materialsDriveUrl || '' } };
});

const sent = $input.all();
if (sent.length !== 9) throw new Error(`Esperados 9 envios de PDF, recebidos ${sent.length}.`);
return [{ json: { ...$('Route State').item.json, sentDocuments: sent.length } }];

