const fs = require('fs');
const path = require('path');
const manifestPath = '/files/manifest.json';
if (!fs.existsSync(manifestPath)) {
  throw new Error('Falta o arquivo /files/manifest.json. Copie materials/manifest.example.json para materials/manifest.json.');
}
const manifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'));
if (!Array.isArray(manifest.documents) || manifest.documents.length !== 9) {
  throw new Error('O manifesto precisa conter exatamente nove PDFs.');
}
const missingFiles = manifest.documents
  .map((doc) => path.join('/files', doc.file))
  .filter((file) => !fs.existsSync(file));
if (missingFiles.length) {
  throw new Error('PDFs ausentes na pasta materials: ' + missingFiles.map((file) => path.basename(file)).join(', '));
}
return [{ json: { ...$json, materialsReady: true } }];

const fs = require('fs');
const path = require('path');
const fileName = 'oferta.jpg';
const fullPath = path.join('/files', fileName);
if (!fs.existsSync(fullPath)) {
  throw new Error('Imagem promocional ausente em /files/oferta.jpg');
}
const offerImageBase64 = fs.readFileSync(fullPath).toString('base64');
return [{ json: { ...$('Route State').item.json, offerImageBase64, offerImageFileName: fileName } }];

